namespace NotificationsApp.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = "";
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<NotificationItem> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        var now = DateTime.UtcNow;
        _notifications.AddRange(new[]
        {
            new NotificationItem { Id = _nextId++, Message = "Welcome to the app!", Timestamp = now.AddMinutes(-10) },
            new NotificationItem { Id = _nextId++, Message = "Your profile was updated.", Timestamp = now.AddMinutes(-5) },
            new NotificationItem { Id = _nextId++, Message = "New feature: dark mode is available.", Timestamp = now.AddMinutes(-2) },
        });
    }

    /// <summary>Returns all notifications ordered newest-first.</summary>
    public List<NotificationItem> GetAll()
    {
        lock (_lock)
        {
            return _notifications.OrderByDescending(n => n.Timestamp).ToList();
        }
    }

    /// <summary>Returns only notifications newer than the given id.</summary>
    public List<NotificationItem> GetSince(int lastSeenId)
    {
        lock (_lock)
        {
            return _notifications
                .Where(n => n.Id > lastSeenId)
                .OrderByDescending(n => n.Timestamp)
                .ToList();
        }
    }

    /// <summary>Simulates an external system pushing a new notification.</summary>
    public NotificationItem Add(string message)
    {
        lock (_lock)
        {
            var item = new NotificationItem
            {
                Id = _nextId++,
                Message = message,
                Timestamp = DateTime.UtcNow,
            };
            _notifications.Add(item);
            return item;
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService Svc
@inject PersistentComponentState PersistState
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h2>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@notifications.Count</span>
</h2>

@if (notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group mt-3">
        @foreach (var n in notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<NotificationItem> notifications = new();
    private CancellationTokenSource? _cts;
    private PersistingComponentStateSubscription _persistSub;

    protected override void OnInitialized()
    {
        // Subscribe to persist the current notifications into the SSR payload
        // so the interactive circuit can pick them up without re-fetching.
        _persistSub = PersistState.RegisterOnPersisting(() =>
        {
            PersistState.PersistAsJson("notifications", notifications);
            return Task.CompletedTask;
        });

        // Try to restore from persisted state (interactive reconnect).
        // If not available, load from the service (first SSR render).
        if (!PersistState.TryTakeFromJson<List<NotificationItem>>("notifications", out var restored))
        {
            notifications = Svc.GetAll();
        }
        else
        {
            notifications = restored!;
        }
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        // OnAfterRender only fires in an interactive context — never during
        // the static SSR pass — so this is the safe place to start polling.
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotifications(_cts.Token);
        }

        await Task.CompletedTask;
    }

    private async Task PollForNotifications(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
            }
            catch (OperationCanceledException)
            {
                break;
            }

            // Simulate a new notification arriving roughly every other poll.
            if (Random.Shared.NextDouble() > 0.5)
            {
                Svc.Add($"Something happened at {DateTime.UtcNow:HH:mm:ss}");
            }

            var lastId = notifications.Count > 0 ? notifications.Max(n => n.Id) : 0;
            var newer = Svc.GetSince(lastId);

            if (newer.Count > 0)
            {
                // Prepend newest items and re-render.
                notifications.InsertRange(0, newer);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _persistSub.Dispose();
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

